            "<text x=\"0\" y=\"0\" style=\"font-size:10px;fill:rgb(200,0,0);fill-opacity:1;stroke:rgb(200,0,0);stroke-width:1;stroke-miterlimit:10;stroke-dasharray:none;stroke-opacity:1;\" xml:space=\"preserve\"> </text>",
            [1, 2],
            2
        )
        == "<text x=\"0\" y=\"0\" style=\"font-size:10px;fill:rgb(200,0,0);fill-opacity:1;stroke:rgb(200,0,0);stroke-width:1;stroke-miterlimit:10;stroke-dasharray:none;stroke-opacity:1;\" xml:space=\"preserve\"> </text>"
